    final ObjectMapper json=new ObjectMapper();
    static Document doc(String text){return new Document("bid","p","BID","投标.pdf",1,"sha","",cn.bidcheck.compat.Java8Api.listOf(new Page(1,text,"PAGE","PDF","")),cn.bidcheck.compat.Java8Api.listOf());}
    static Rule rule(String predicate,String subject,String field,String expected,Map<String,Object> params){return new Rule("O1","测试条件",predicate,subject,field,">=",expected,"",params,"真实要求","",cn.bidcheck.compat.Java8Api.listOf());}
    static Fact fact(String kind,String subject,String field,String value,String unit,String basis,Map<String,Object> attrs,EvidenceCorpus corpus){return new Fact("f"+value,kind,subject,field,value,value,unit,basis,"CURRENT_PROJECT",cn.bidcheck.compat.Java8Api.listOf(corpus.all.get(0).id()),attrs);}
    static RuleEvaluator evaluator(EvidenceCorpus c,List<Fact> f){return new RuleEvaluator(f,c,cn.bidcheck.compat.Java8Api.mapOf());}
    @Test void emptyAllAndAnyNeverPass(){for(String logic:cn.bidcheck.compat.Java8Api.listOf("ALL", "ANY"))assertEquals("UNDETERMINED",RuleEvaluator.combine("id","text",logic,cn.bidcheck.compat.Java8Api.listOf()).status());}
    @Test void anyWithUnknownAlternativeCannotFail(){Decision fail=new Decision("a","","FAIL","",cn.bidcheck.compat.Java8Api.listOf(),cn.bidcheck.compat.Java8Api.listOf(),cn.bidcheck.compat.Java8Api.mapOf());Decision unknown=new Decision("b","","UNDETERMINED","",cn.bidcheck.compat.Java8Api.listOf(),cn.bidcheck.compat.Java8Api.listOf(gap("INPUT","missing")),cn.bidcheck.compat.Java8Api.mapOf());assertEquals("UNDETERMINED",RuleEvaluator.combine("id","","ANY",cn.bidcheck.compat.Java8Api.listOf(fail, unknown)).status());}
    @Test void anyCompleteProofMayPassWithoutUnneededBranch(){Decision pass=new Decision("a","","PASS","",cn.bidcheck.compat.Java8Api.listOf(),cn.bidcheck.compat.Java8Api.listOf(),cn.bidcheck.compat.Java8Api.mapOf());Decision unknown=new Decision("b","","UNDETERMINED","",cn.bidcheck.compat.Java8Api.listOf(),cn.bidcheck.compat.Java8Api.listOf(gap("INPUT","missing")),cn.bidcheck.compat.Java8Api.mapOf());Decision result=RuleEvaluator.combine("id","","ANY",cn.bidcheck.compat.Java8Api.listOf(pass, unknown));assertEquals("PASS",result.status());assertTrue(result.gaps().isEmpty());}
    @Test void emptyForeachDoesNotProvePopulation(){EvidenceCorpus c=new EvidenceCorpus(cn.bidcheck.compat.Java8Api.listOf(doc("人员资料")));Rule r=new Rule("a","全部成员","","","","","","",cn.bidcheck.compat.Java8Api.mapOf(),"全体成员","FOR_EACH",cn.bidcheck.compat.Java8Api.listOf(rule("MATERIAL","","","证书",cn.bidcheck.compat.Java8Api.mapOf())));assertEquals("UNDETERMINED",evaluator(c,cn.bidcheck.compat.Java8Api.listOf()).evaluate(r).status());}
    @Test void decimalPointAndTableWhitespacePreserved(){assertFalse(ProofVerifier.numberPresent("总价 123 万元","12.3"));assertTrue(ProofVerifier.numberPresent("金额 1,234.50 万元","1234.50"));assertTrue(ProofVerifier.numberPresent("序号 1 335.06 单价 20","335.06"));assertFalse(ProofVerifier.numberPresent("序号 1 335.06","1335.06"));}
    @Test void quotedAmountCannotBorrowAnotherBasis(){EvidenceCorpus c=new EvidenceCorpus(cn.bidcheck.compat.Java8Api.listOf(doc("总工程造价：1335.06万元。建安费用：200万元。")));Fact f=fact("NUMBER","合同","amount","1335.06","万元","建安费用",cn.bidcheck.compat.Java8Api.mapOf(),c);assertNotNull(new ProofVerifier().issue(f,c.byId));}
    @Test void modelCannotCiteUnknownSource()throws Exception{EvidenceCorpus c=new EvidenceCorpus(cn.bidcheck.compat.Java8Api.listOf(doc("金额：12元")));cn.bidcheck.verification.engine.ProofVerifier.Verified result=new ProofVerifier().verify(json.readTree("{\"facts\":[{\"kind\":\"NUMBER\",\"rawValue\":\"12\",\"sourceIds\":[\"foreign\"]}]}"),c.all);assertTrue(result.facts().isEmpty());assertEquals("SOURCE_REFERENCE_INVALID",result.rejected().get(0).get("code"));}
    @Test void directoryDoesNotProveSection(){EvidenceCorpus c=new EvidenceCorpus(cn.bidcheck.compat.Java8Api.listOf(doc("目录\n技术方案……20\n施工进度……30\n")));Fact f=fact("SECTION","","","技术方案","","",cn.bidcheck.compat.Java8Api.mapOf(),c);assertEquals("NAVIGATION_NOT_SUBSTANTIVE",new ProofVerifier().issue(f,c.byId));}
    @Test void disjointMonthsCannotProveContinuity(){EvidenceCorpus c=new EvidenceCorpus(cn.bidcheck.compat.Java8Api.listOf(doc("参保人：测试甲 2025年1月 2025年3月 2025年5月")));Fact f=fact("MONTHS","测试甲","","社保","","",cn.bidcheck.compat.Java8Api.mapOf("person", "测试甲", "months", cn.bidcheck.compat.Java8Api.listOf("2025-01", "2025-03", "2025-05")),c);assertEquals("UNDETERMINED",evaluator(c,cn.bidcheck.compat.Java8Api.listOf(f)).evaluate(rule("MONTHS","测试甲","","",cn.bidcheck.compat.Java8Api.mapOf("count", 3, "earliestMonth", "2024-12"))).status());}
    @Test void optionalWindowDoesNotRequireFirstMonth(){EvidenceCorpus c=new EvidenceCorpus(cn.bidcheck.compat.Java8Api.listOf(doc("社保：2025年1月 2025年2月 2025年3月")));Fact f=fact("MONTHS","甲","","社保","","",cn.bidcheck.compat.Java8Api.mapOf("months", cn.bidcheck.compat.Java8Api.listOf("2025-01", "2025-02", "2025-03")),c);assertEquals("PASS",evaluator(c,cn.bidcheck.compat.Java8Api.listOf(f)).evaluate(rule("MONTHS","甲","","",cn.bidcheck.compat.Java8Api.mapOf("count", 3, "earliestMonth", "2024-12"))).status());}
    @Test void expiredCertificateAndUnconfirmedTimeRemainDistinct(){EvidenceCorpus c=new EvidenceCorpus(cn.bidcheck.compat.Java8Api.listOf(doc("姓名：甲 注册证书 证书编号：R001 有效期2024年1月1日至2025年1月1日")));Fact f=fact("CERTIFICATE","甲","","注册证书","","",cn.bidcheck.compat.Java8Api.mapOf("category", "注册证书", "number", "R001", "numberField", "证书编号", "validityField", "有效期", "start", "2024-01-01", "end", "2025-01-01"),c);Rule r=rule("VALIDITY","甲","有效期","",cn.bidcheck.compat.Java8Api.mapOf("category", "注册证书", "validityField", "有效期"));assertEquals("UNDETERMINED",evaluator(c,cn.bidcheck.compat.Java8Api.listOf(f)).evaluate(r).status());Map<String,Object> ctx=new HashMap<>(cn.bidcheck.compat.Java8Api.mapOf("referenceDate", "2025-08-01", "referenceDateSource", "t", "referenceDateSourceVerified", true, "referenceDateEvidence", cn.bidcheck.compat.Java8Api.mapOf("documentId", "t", "quote", "投标截止2025年8月1日", "confirmation", "USER_SELECTED_VERSION")));assertEquals("FAIL",new RuleEvaluator(cn.bidcheck.compat.Java8Api.listOf(f),c,ctx).evaluate(r).status());}
    @Test void relationshipNeedsBothEndpoints(){EvidenceCorpus c=new EvidenceCorpus(cn.bidcheck.compat.Java8Api.listOf(doc("甲公司承担设计工作。")));Fact f=fact("RELATION","测试甲","所属单位","","","",cn.bidcheck.compat.Java8Api.mapOf("object", "甲公司"),c);assertEquals("RAW_VALUE_UNGROUNDED",new ProofVerifier().issue(f,c.byId));}
    @Test void graphTraversesOnlySourcedOrderedEdges(){EvidenceCorpus c=new EvidenceCorpus(cn.bidcheck.compat.Java8Api.listOf(doc("测试甲所属甲公司，甲公司负责设计")));Fact a=fact("RELATION","测试甲","所属单位","甲公司","","",cn.bidcheck.compat.Java8Api.mapOf("object", "甲公司"),c),b=fact("RELATION","甲公司","负责","设计","","",cn.bidcheck.compat.Java8Api.mapOf("object", "设计"),c);Rule r=rule("RELATION","测试甲","","设计",cn.bidcheck.compat.Java8Api.mapOf("path", cn.bidcheck.compat.Java8Api.listOf("所属单位", "负责")));assertEquals("PASS",evaluator(c,cn.bidcheck.compat.Java8Api.listOf(a, b)).evaluate(r).status());assertEquals("UNDETERMINED",evaluator(c,cn.bidcheck.compat.Java8Api.listOf(b)).evaluate(r).status());}
    @Test void unsupportedTaxOrAmountBasisDoesNotPass(){EvidenceCorpus c=new EvidenceCorpus(cn.bidcheck.compat.Java8Api.listOf(doc("合同总价500万元")));Fact f=fact("CONTRACT","X","","合同总价500万元","","",cn.bidcheck.compat.Java8Api.mapOf("contractName", "测试合同", "amount", "500", "unit", "万元", "amountBasis", "总价"),c);Rule r=new Rule("r","建安费要求","CONTRACT","","","","","万元",cn.bidcheck.compat.Java8Api.mapOf("amountMinimum", 200, "amountBasis", "建安费"),"建安费至少200万元","",cn.bidcheck.compat.Java8Api.listOf());assertEquals("UNDETERMINED",evaluator(c,cn.bidcheck.compat.Java8Api.listOf(f)).evaluate(r).status());}
    @Test void contractScoreDeduplicatesSameContract(){EvidenceCorpus c=new EvidenceCorpus(cn.bidcheck.compat.Java8Api.listOf(doc("合同编号ABC，金额100万元")));Fact f=fact("CONTRACT","ABC","","合同","","",cn.bidcheck.compat.Java8Api.mapOf("contractNumber", "ABC", "contractName", "工程合同", "party", "甲公司"),c);Fact duplicate=new Fact("copy",f.kind(),f.subject(),f.field(),f.rawValue(),f.value(),f.unit(),f.basis(),f.scope(),f.sourceIds(),f.attributes());Rule r=new Rule("score","每项2分","SCORE_COUNT","","","","","",cn.bidcheck.compat.Java8Api.mapOf("pointsPerItem", 2, "maxScore", 10),"每项2分最多10分","ALL",cn.bidcheck.compat.Java8Api.listOf(rule("CONTRACT","","","",cn.bidcheck.compat.Java8Api.mapOf())));Decision out=new RuleEvaluator(cn.bidcheck.compat.Java8Api.listOf(f, duplicate),c,cn.bidcheck.compat.Java8Api.mapOf("contractSetComplete", true)).evaluate(r);assertEquals("PASS",out.status());assertEquals("2",out.proof().get("score").toString());}
    @Test void importedExternalRecordIsNotTrusted(){EvidenceCorpus c=new EvidenceCorpus(cn.bidcheck.compat.Java8Api.listOf(doc("我们承诺无禁入记录")));Map<String,Object> ctx=cn.bidcheck.compat.Java8Api.mapOf("externalRecords", cn.bidcheck.compat.Java8Api.listOf(cn.bidcheck.compat.Java8Api.mapOf("type", "blacklist", "subject", "甲", "provenanceStatus", "PROVIDED_NOT_AUTHENTICATED", "result", "PASS")));assertEquals("UNDETERMINED",new RuleEvaluator(cn.bidcheck.compat.Java8Api.listOf(),c,ctx).evaluate(rule("EXTERNAL","甲","blacklist","false",cn.bidcheck.compat.Java8Api.mapOf())).status());}
    @Test void validTrustedExternalFieldCanCloseAtomicRequirement(){EvidenceCorpus c=new EvidenceCorpus(cn.bidcheck.compat.Java8Api.listOf(doc("甲单位资料")));Map<String,Object> record=linked("id","e","type","BLACKLIST","subject","甲","provenanceStatus","TRUSTED_CONNECTOR","rawSnapshotHash","hash","source","official","queriedAt","2025-08-01T10:00:00Z","coverageComplete",true,"result",cn.bidcheck.compat.Java8Api.mapOf("status", "VERIFIED", "facts", cn.bidcheck.compat.Java8Api.listOf(cn.bidcheck.compat.Java8Api.mapOf("field", "listed", "value", "false", "rawValue", "未列入", "sourceQuote", "甲：未列入"))));Rule r=new Rule("r","名单核查","EXTERNAL","甲","listed","=","false","",cn.bidcheck.compat.Java8Api.mapOf("externalType", "BLACKLIST"),"甲不在禁入名单","",cn.bidcheck.compat.Java8Api.listOf());assertEquals("PASS",new RuleEvaluator(cn.bidcheck.compat.Java8Api.listOf(),c,cn.bidcheck.compat.Java8Api.mapOf("externalRecords", cn.bidcheck.compat.Java8Api.listOf(record))).evaluate(r).status());}
    @Test void foreignProjectRejectedBeforeModel(){VerificationEngine e=new VerificationEngine();Document foreign=new Document("b2","foreign","BID","",1,"sha2","",cn.bidcheck.compat.Java8Api.listOf(),cn.bidcheck.compat.Java8Api.listOf());assertThrows(IllegalArgumentException.class,()->e.evaluate(cp(),cn.bidcheck.compat.Java8Api.listOf(doc("文字"), foreign),null,cn.bidcheck.compat.Java8Api.mapOf()));}
    static Checkpoint cp(){return new Checkpoint("c","承诺书提交","组成","一般","SEMANTIC_RESPONSE","","","提交守法承诺书","",true,true,true,null);}
    @Test void completedPaidStepsResumeAndInputChangeInvalidatesExtraction()throws Exception{
        AtomicInteger calls=new AtomicInteger();ModelGateway gateway=new ModelGateway(){public boolean enabled(){return true;}public String identity(){return "test-model-v1";}public JsonNode request(String op,Map<String,Object> input){calls.incrementAndGet();if(op.equals("COMPILE"))return json.valueToTree(cn.bidcheck.compat.Java8Api.mapOf("logic", "ALL", "rules", cn.bidcheck.compat.Java8Api.listOf(cn.bidcheck.compat.Java8Api.mapOf("id", "O1", "predicate", "DECLARATION", "description", "提交守法承诺书", "expected", "守法承诺书", "sourceQuote", "提交守法承诺书"))));List<Map<String,Object>> sources=(List<Map<String,Object>>)input.get("sources");return json.valueToTree(cn.bidcheck.compat.Java8Api.mapOf("facts", cn.bidcheck.compat.Java8Api.listOf(cn.bidcheck.compat.Java8Api.mapOf("kind", "DECLARATION", "rawValue", "守法承诺书", "value", "守法承诺书", "scope", "CURRENT_PROJECT", "sourceIds", cn.bidcheck.compat.Java8Api.listOf(sources.get(0).get("id"))))));}};
        VerificationEngine engine=new VerificationEngine(gateway,null);Document d=doc("守法承诺书\n我们承诺遵守法律并承担相关责任。相关义务按照本项目招标要求履行，所有声明均由本公司出具。声明正文结束。");Map<String,Object> first=engine.evaluate(cp(),cn.bidcheck.compat.Java8Api.listOf(d),null,cn.bidcheck.compat.Java8Api.mapOf());assertEquals("PASS",first.get("businessDecision"));int initial=calls.get();Map<String,Object> second=engine.evaluate(cp(),cn.bidcheck.compat.Java8Api.listOf(d),null,cn.bidcheck.compat.Java8Api.mapOf("priorSteps", first.get("steps")));assertEquals("PASS",second.get("businessDecision"));assertEquals(initial,calls.get());
        Document changed=new Document(d.id(),d.projectId(),d.role(),d.name(),2,"newHash","",d.pages(),d.warnings());engine.evaluate(cp(),cn.bidcheck.compat.Java8Api.listOf(changed),null,cn.bidcheck.compat.Java8Api.mapOf("priorSteps", first.get("steps"), "maxModelCalls", 8));assertEquals(initial+1,calls.get());}
    @Test void failedAttemptsConsumePersistentBudget()throws Exception{AtomicInteger calls=new AtomicInteger();ModelGateway gateway=new ModelGateway(){public boolean enabled(){return true;}public String identity(){return "fail";}public JsonNode request(String op,Map<String,Object> input)throws IOException{calls.incrementAndGet();throw new IOException("network");}};List<Map<String,Object>> saved=new ArrayList<>();Map<String,Object> ctx=new HashMap<>();ctx.put("maxModelCalls",1);ctx.put("stepObserver",(Consumer<Map<String,Object>>)saved::add);RunSession first=new RunSession(gateway,ctx,"doc");assertThrows(IOException.class,()->first.model("EXTRACT",cn.bidcheck.compat.Java8Api.mapOf("data", "x")));RunSession retry=new RunSession(gateway,cn.bidcheck.compat.Java8Api.mapOf("maxModelCalls", 1, "priorSteps", saved),"doc");assertThrows(IOException.class,()->retry.model("EXTRACT",cn.bidcheck.compat.Java8Api.mapOf("data", "x")));assertEquals(1,calls.get());}
    @Test void leaseObserverFailureStopsBeforePaidCall(){AtomicInteger calls=new AtomicInteger();ModelGateway gateway=new ModelGateway(){public boolean enabled(){return true;}public String identity(){return "test";}public JsonNode request(String op,Map<String,Object> input){calls.incrementAndGet();return json.createObjectNode();}};RunSession s=new RunSession(gateway,cn.bidcheck.compat.Java8Api.mapOf("stepObserver", (Consumer<Map<String,Object>>)m->{throw new IllegalStateException("lease lost");}),"scope");assertThrows(IllegalStateException.class,()->s.model("EXTRACT",cn.bidcheck.compat.Java8Api.mapOf()));assertEquals(0,calls.get());}
    @Test void modelCannotInventCompiledAmountThreshold()throws Exception{ModelGateway gateway=new ModelGateway(){public boolean enabled(){return true;}public String identity(){return "compile";}public JsonNode request(String o,Map<String,Object> i){return json.valueToTree(cn.bidcheck.compat.Java8Api.mapOf("logic", "ALL", "rules", cn.bidcheck.compat.Java8Api.listOf(cn.bidcheck.compat.Java8Api.mapOf("id", "a", "predicate", "CONTRACT", "sourceQuote", "金额不少于200万元", "parameters", cn.bidcheck.compat.Java8Api.mapOf("amountMinimum", 20)))));}};Checkpoint c=new Checkpoint("c","业绩","评分","","SEMANTIC_RESPONSE","","","金额不少于200万元","",true,true,true,null);Plan p=new RequirementCompiler().compile(c,new RunSession(gateway,cn.bidcheck.compat.Java8Api.mapOf(),"s"));assertEquals(1,p.rules().size());assertEquals("UNSUPPORTED",p.rules().get(0).predicate());assertEquals("金额不少于200万元",p.rules().get(0).sourceQuote());assertTrue(p.rules().get(0).parameters().containsKey("compilationIssue"));assertFalse(p.issues().isEmpty());assertEquals("UNDETERMINED",new RuleEvaluator(cn.bidcheck.compat.Java8Api.listOf(),new EvidenceCorpus(cn.bidcheck.compat.Java8Api.listOf(doc("业绩材料"))),cn.bidcheck.compat.Java8Api.mapOf()).evaluate(p.rules().get(0)).status());}
